import java.util.*;
class PageTree {static class P{List<Integer> keys=new ArrayList<>();List<P> children=new ArrayList<>();P next;}record Split(int key,P right){}P root=new P();final boolean plus;Set<Integer> seen=new HashSet<>();PageTree(boolean plus){this.plus=plus;}
Split insert(P p,int k){int i=0;while(i<p.keys.size()&&(k>p.keys.get(i)||(plus&&k==p.keys.get(i))))i++;if(!p.children.isEmpty()){Split s=insert(p.children.get(i),k);if(s!=null){p.keys.add(i,s.key());p.children.add(i+1,s.right());}}else p.keys.add(i,k);if(p.keys.size()<=3)return null;
P r=new P();if(plus&&p.children.isEmpty()){r.keys.addAll(p.keys.subList(2,p.keys.size()));p.keys.subList(2,p.keys.size()).clear();r.next=p.next;p.next=r;return new Split(r.keys.get(0),r);}int key=p.keys.get(2);r.keys.addAll(p.keys.subList(3,p.keys.size()));p.keys.subList(2,p.keys.size()).clear();if(!p.children.isEmpty()){r.children.addAll(p.children.subList(3,p.children.size()));p.children.subList(3,p.children.size()).clear();}return new Split(key,r);}
void add(int k){if(!seen.add(k))return;Split s=insert(root,k);if(s!=null){P p=new P();p.keys.add(s.key());p.children.add(root);p.children.add(s.right());root=p;}}
boolean has(int k){P p=root;while(true){int i=0;while(i<p.keys.size()&&k>p.keys.get(i))i++;if(p.children.isEmpty())return p.keys.contains(k);if(i<p.keys.size()&&p.keys.get(i)==k){if(!plus)return true;i++;}p=p.children.get(i);}}}
